#!/bin/bash
set -eo pipefail
BASE=/data1/home/sunyiq/china_soil_classification_12_hpc_20261014_001
test ! -e "$BASE"
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'PY_DEPLOY'
import base64,hashlib,io,json,pathlib,tarfile
base=pathlib.Path('/data1/home/sunyiq/china_soil_classification_12_hpc_20261014_001')
root=base/'preflight_v1'
packed=base64.b64decode('',validate=True)
expected=json.loads('{"preflight.py":{"bytes":11682,"sha256":"40857a219df4dbd51fbfa2b08685dda5eac648978710690e70e8ec8f37ea7c2c"},"preflight.sbatch":{"bytes":953,"sha256":"fd7879e9c3f53ec2be3c08fbb5abb8bab3905eb01312de06a13794eae1e2b0cf"},"PREFLIGHT_CONTRACT.json":{"bytes":4235,"sha256":"867552c6fec97f0c5d9ad110fb45d509a549f6068449db998b2d626844d7afce"},"PILOT_GEOMETRY_BYTES.geojson":{"bytes":49531,"sha256":"5396a4c8f7e12d8ace0e55be9b42ec84b966778923b41aa58dcec6275a98896b"},"OLD_SOIL_REFERENCE_BYTES.csv":{"bytes":334182,"sha256":"1ce8a13e33f4fb4db89c072a5de1680b46726e595b9b162dd66ec8fdbc4ce8e2"}}')
assert len(packed)==171580 and hashlib.sha256(packed).hexdigest()=='70603369bf5f6b249b39364e13e9d43d7750ef4979ff3607a74279118b1297a8'
assert len(packed)<=2097152 and len(expected)==5 and sum(x['bytes'] for x in expected.values())<=2097152
assert not base.exists()
contents={}
with tarfile.open(fileobj=io.BytesIO(packed),mode='r:gz') as archive:
    members=archive.getmembers()
    assert len(members)==5 and {m.name for m in members}==set(expected)
    for member in members:
        assert member.isfile() and member.name in expected and member.size<=1048576
        raw=archive.extractfile(member).read(1048577)
        assert len(raw)==member.size==expected[member.name]['bytes']
        assert hashlib.sha256(raw).hexdigest()==expected[member.name]['sha256']
        contents[member.name]=raw
base.mkdir()
root.mkdir()
(root/'logs').mkdir()
for name,raw in contents.items():
    with (root/name).open('xb') as stream:stream.write(raw)
print('OWN_METADATA_DEPLOY_BYTES_VERIFIED',flush=True)
PY_DEPLOY
cd "$BASE/preflight_v1"
set +e
submitted=$(sbatch preflight.sbatch 2>&1)
code=$?
set -e
printf '%s\n' "$submitted"
printf 'OWN_METADATA_SUBMIT_EXIT=%s\n' "$code"
test "$code" = 0
[[ "$submitted" =~ ^Submitted\ batch\ job\ ([0-9]+)$ ]]
job="${BASH_REMATCH[1]}"
test ! -e OWN_METADATA_JOB_ID
(set -o noclobber; printf '%s\n' "$job" > OWN_METADATA_JOB_ID)
printf 'OWN_METADATA_JOB_ID=%s\n' "$job"
printf 'OWN_METADATA_SUBMIT_DONE\n'
